<template><div class="task-page"><el-tabs v-model="tab"><el-tab-pane label="提醒列表" name="reminders"><el-card><template #header><div class="task-card-header"><span>提醒</span><el-button type="primary" @click="openReminder()">新建提醒</el-button></div></template><section class="gold-alert-rules"><div class="rule-heading"><div><b>金价监控提醒</b><small>后台每 5 分钟自动检查，价格回升后再次跌破会重新提醒</small></div><div><el-button link type="primary" @click="$router.push('/gold')">查看实时金价</el-button><el-button type="primary" @click="openGoldRule()">新增规则</el-button></div></div><div class="rule-grid"><article v-for="rule in goldAlertRules" :key="rule.alertKey"><div class="rule-title"><b>{{rule.title}}</b><el-tag :type="ruleStatusType(rule.status)">{{ruleStatusName(rule.status)}}</el-tag></div><p>{{rule.condition}}</p><small>检查频率：{{rule.checkInterval}}<template v-if="rule.lastPrice!==null"> · 最近价格：{{rule.lastPrice}} 元/克</template></small><small v-if="rule.lastNotifiedAt">最近通知：{{formatTime(rule.lastNotifiedAt)}}</small><div class="rule-actions"><el-button link type="primary" @click="openGoldRule(rule)">编辑</el-button><el-switch :model-value="rule.enabled" @change="onGoldRuleToggle(rule,$event)"/><el-button link type="danger" @click="removeGoldRule(rule)">删除</el-button></div></article></div><el-alert v-if="goldAlertRules.some(rule=>rule.enabled&&!rule.channelConfigured)" title="金价监控规则已启用，但需要先在“通知通道”中配置并启用通道才能收到消息。" type="warning" :closable="false" show-icon/></section><el-select v-model="status" clearable placeholder="全部状态" class="status-filter" @change="loadReminders"><el-option v-for="option in statuses" :key="option.value" :label="option.label" :value="option.value"/></el-select><el-table class="desktop-table" :data="reminders"><el-table-column prop="title" label="标题"/><el-table-column prop="sourceType" label="来源" width="100"/><el-table-column prop="remindTime" label="提醒时间" width="180"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag>{{statusName(row.status)}}</el-tag></template></el-table-column><el-table-column prop="lastError" label="失败原因"/><el-table-column label="操作" width="190"><template #default="{row}"><el-button v-if="row.status==='PENDING'" link type="primary" @click="openReminder(row)">编辑</el-button><el-button v-if="row.status==='PENDING'" link type="success" @click="setStatus(row,'COMPLETED')">完成</el-button><el-button v-if="row.status==='PENDING'" link type="danger" @click="setStatus(row,'CANCELLED')">取消</el-button></template></el-table-column></el-table><div class="mobile-cards"><article v-for="row in reminders" :key="row.id"><div class="card-top"><b>{{row.title}}</b><el-tag>{{statusName(row.status)}}</el-tag></div><p>{{row.content||'无补充内容'}}</p><time>{{formatTime(row.remindTime)}}</time><div v-if="row.status==='PENDING'" class="card-actions"><el-button plain type="primary" @click="openReminder(row)">编辑</el-button><el-button plain type="success" @click="setStatus(row,'COMPLETED')">完成</el-button><el-button plain type="danger" @click="setStatus(row,'CANCELLED')">取消</el-button></div></article></div><el-empty v-if="!reminders.length" description="暂无提醒"/></el-card></el-tab-pane>
<el-tab-pane label="通知通道" name="channels"><el-card><template #header><div class="task-card-header"><span>通知通道</span><el-button type="primary" @click="channelVisible=true">新增通道</el-button></div></template><el-table class="desktop-table" :data="channels"><el-table-column prop="name" label="名称"/><el-table-column prop="channelType" label="类型"/><el-table-column prop="maskedWebhook" label="Webhook（已脱敏）"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="sendTest(row)">测试发送</el-button><el-button link type="danger" @click="removeChannel(row)">删除</el-button></template></el-table-column></el-table><div class="mobile-cards"><article v-for="row in channels" :key="row.id"><div class="card-top"><b>{{row.name}}</b><el-tag :type="row.enabled?'success':'info'">{{row.channelType}}</el-tag></div><p>{{row.maskedWebhook}}</p><div class="card-actions"><el-button type="primary" plain @click="sendTest(row)">测试发送</el-button><el-button type="danger" plain @click="removeChannel(row)">删除</el-button></div></article></div></el-card></el-tab-pane>
<el-tab-pane label="发送日志" name="logs"><el-card><el-table class="desktop-table" :data="logs"><el-table-column prop="createdAt" label="时间" width="180"/><el-table-column prop="reminderId" label="提醒 ID"/><el-table-column prop="channelId" label="通道 ID"/><el-table-column label="结果"><template #default="{row}"><el-tag :type="row.success?'success':'danger'">{{row.success?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column prop="message" label="信息"/></el-table><div class="mobile-cards"><article v-for="row in logs" :key="row.id"><div class="card-top"><time>{{formatTime(row.createdAt)}}</time><el-tag :type="row.success?'success':'danger'">{{row.success?'成功':'失败'}}</el-tag></div><p>{{row.message}}</p></article></div></el-card></el-tab-pane></el-tabs>
<el-dialog v-model="goldRuleVisible" :title="goldRuleEditing?'编辑金价提醒规则':'新增金价提醒规则'" width="560px"><el-form :model="goldRuleForm" label-width="100px"><el-form-item label="规则名称" required><el-input v-model="goldRuleForm.title" placeholder="例如：实时金价跌破 800 元/克"/></el-form-item><el-form-item label="金价类型"><el-input model-value="实时折算金价" disabled/></el-form-item><el-form-item label="跌破阈值" required><el-input-number v-model="goldRuleForm.threshold" :min="0.01" :precision="2" style="width:100%"/><span class="form-tip">元/克</span></el-form-item><el-form-item label="启用"><el-switch v-model="goldRuleForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="goldRuleVisible=false">取消</el-button><el-button type="primary" @click="saveGoldRule">保存</el-button></template></el-dialog><el-dialog v-model="reminderVisible" title="提醒" width="600px"><el-form :model="form" label-width="90px"><el-form-item label="标题" required><el-input v-model="form.title"/></el-form-item><el-form-item label="来源"><el-select v-model="form.sourceType"><el-option label="生活事项" value="LIFE"/><el-option label="工作事项" value="WORK"/><el-option label="学习计划" value="LEARNING"/><el-option label="自定义" value="CUSTOM"/></el-select></el-form-item><el-form-item label="通知通道"><el-select v-model="form.channelId" clearable><el-option v-for="channel in channels" :key="channel.id" :label="channel.name" :value="channel.id"/></el-select></el-form-item><el-form-item label="提醒时间"><el-date-picker v-model="form.remindTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="内容"><el-input v-model="form.content" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="reminderVisible=false">取消</el-button><el-button type="primary" @click="saveReminder">保存</el-button></template></el-dialog>
<el-dialog v-model="channelVisible" title="新增通知通道" width="560px"><el-form :model="channelForm" label-width="90px"><el-form-item label="名称"><el-input v-model="channelForm.name"/></el-form-item><el-form-item label="Webhook"><el-input v-model="channelForm.webhook" type="password" show-password placeholder="支持 Server酱 https://sctapi.ftqq.com/...send"/></el-form-item><el-form-item label="启用"><el-switch v-model="channelForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="channelVisible=false">取消</el-button><el-button type="primary" @click="saveChannelForm">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import { ElMessage, ElMessageBox } from 'element-plus';
import { onMounted, reactive, ref, watch } from 'vue';
import { deleteGoldPriceAlertRule, listGoldPriceAlertRules, saveGoldPriceAlertRule, toggleGoldPriceAlertRule, updateGoldPriceAlertRule, type GoldPriceAlertRule, type GoldPriceAlertRulePayload } from '@/api/gold';
import { changeReminderStatus, createReminder, deleteChannel, listChannels, listNotificationLogs, listReminders, saveChannel, testChannel, updateReminder, type Channel, type NotificationLog, type Reminder, type ReminderPayload } from '@/api/reminder';

const tab = ref('reminders');
const status = ref('');
const reminders = ref<Reminder[]>([]);
const goldAlertRules = ref<GoldPriceAlertRule[]>([]);
const goldRuleVisible = ref(false);
const goldRuleEditing = ref<number>();
const blankGoldRule = (): GoldPriceAlertRulePayload => ({ title: '', quoteType: 'MARKET', threshold: 800, brandNames: null, enabled: true });
const goldRuleForm = reactive<GoldPriceAlertRulePayload>(blankGoldRule());
const channels = ref<Channel[]>([]);
const logs = ref<NotificationLog[]>([]);
const reminderVisible = ref(false);
const channelVisible = ref(false);
const editing = ref<number>();
const statuses = [{ label: '待触发', value: 'PENDING' }, { label: '已发送', value: 'SENT' }, { label: '失败', value: 'FAILED' }, { label: '已完成', value: 'COMPLETED' }, { label: '已取消', value: 'CANCELLED' }];
const now = () => {
  const date = new Date(Date.now() + 3600000);
  date.setMinutes(date.getMinutes() - date.getTimezoneOffset());
  return date.toISOString().slice(0, 19);
};
const blank = (): ReminderPayload => ({ sourceType: 'CUSTOM', sourceId: null, channelId: null, title: '', content: '', remindTime: now() });
const form = reactive(blank());
const channelForm = reactive({ name: '', channelType: 'WEBHOOK', webhook: '', enabled: true });

function ruleStatusName(value: GoldPriceAlertRule['status']) { return { MONITORING: '监控中', TRIGGERED: '已触发', NO_CHANNEL: '未配置通道', DISABLED: '已停用' }[value]; }
function ruleStatusType(value: GoldPriceAlertRule['status']) { return value === 'TRIGGERED' ? 'warning' : value === 'NO_CHANNEL' ? 'danger' : value === 'DISABLED' ? 'info' : 'success'; }
function openGoldRule(rule?: GoldPriceAlertRule) { goldRuleEditing.value=rule?.id; Object.assign(goldRuleForm,blankGoldRule(),rule?{title:rule.title,quoteType:rule.quoteType,threshold:rule.threshold,brandNames:rule.brandNames,enabled:rule.enabled}:{}); goldRuleVisible.value=true; }
async function saveGoldRule() { if(!goldRuleForm.title||!goldRuleForm.threshold){ElMessage.warning('请填写规则名称和阈值');return;} goldRuleEditing.value?await updateGoldPriceAlertRule(goldRuleEditing.value,goldRuleForm):await saveGoldPriceAlertRule(goldRuleForm); goldRuleVisible.value=false; ElMessage.success('金价提醒规则已保存'); await loadGoldAlertRules(); }
function onGoldRuleToggle(rule:GoldPriceAlertRule,value:string|number|boolean){void toggleGoldRule(rule,Boolean(value));}
async function toggleGoldRule(rule:GoldPriceAlertRule,enabled:boolean){await toggleGoldPriceAlertRule(rule.id,enabled);await loadGoldAlertRules();}
async function removeGoldRule(rule:GoldPriceAlertRule){await ElMessageBox.confirm(`确认删除“${rule.title}”？`,'删除确认',{type:'warning'});await deleteGoldPriceAlertRule(rule.id);await loadGoldAlertRules();}async function loadGoldAlertRules() { goldAlertRules.value = (await listGoldPriceAlertRules()).data; }function statusName(value: string) { return statuses.find(item => item.value === value)?.label || value; }
function formatTime(value: string) { return new Date(value).toLocaleString('zh-CN', { hour12: false }); }
async function loadReminders() { reminders.value = (await listReminders(status.value)).data; }
async function loadChannels() { channels.value = (await listChannels()).data; }
function openReminder(row?: Reminder) { editing.value = row?.id; Object.assign(form, blank(), row || {}); reminderVisible.value = true; }
async function saveReminder() {
  if (!form.title || !form.remindTime) { ElMessage.warning('请填写标题和提醒时间'); return; }
  if (editing.value) await updateReminder(editing.value, form); else await createReminder(form);
  reminderVisible.value = false;
  await loadReminders();
}
async function setStatus(row: Reminder, value: string) { await changeReminderStatus(row.id, value); await loadReminders(); }
async function saveChannelForm() {
  if (!channelForm.name || !channelForm.webhook) { ElMessage.warning('请填写名称和 Webhook'); return; }
  await saveChannel(channelForm);
  channelVisible.value = false;
  await loadChannels();
}
async function sendTest(channel: Channel) { await testChannel(channel.id); ElMessage.success('测试消息发送成功'); }
async function removeChannel(channel: Channel) {
  await ElMessageBox.confirm(`确认删除通知通道“${channel.name}”？删除后无法恢复。`, '删除确认', { type: 'warning' });
  await deleteChannel(channel.id);
  ElMessage.success('通知通道已删除');
  await Promise.all([loadChannels(), loadReminders(), loadGoldAlertRules()]);
}
watch(tab, async value => {
  if (value === 'logs') logs.value = (await listNotificationLogs()).data;
  if (value === 'channels') await loadChannels();
});
onMounted(async () => { await Promise.all([loadReminders(), loadChannels(), loadGoldAlertRules()]); });
</script>
<style scoped>.gold-alert-rules{margin-bottom:20px;padding:16px;border:1px solid #dbeafe;border-radius:14px;background:linear-gradient(135deg,#eff6ff,#f0fdfa)}.rule-heading,.rule-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.rule-heading small,.gold-alert-rules article small{display:block;color:#64748b;margin-top:4px}.rule-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:14px 0}.rule-grid article{padding:14px;background:#fff;border:1px solid #e2e8f0;border-radius:12px}.rule-grid p{margin:10px 0;color:#334155}.rule-actions{display:flex;align-items:center;justify-content:flex-end;gap:10px;margin-top:10px;padding-top:8px;border-top:1px solid #f1f5f9}.form-tip{display:block;width:100%;font-size:12px;color:#64748b}.status-filter{width:140px;margin-bottom:16px}.mobile-cards{display:none}@media(max-width:768px){.rule-grid{grid-template-columns:1fr}.rule-heading{align-items:flex-start}.desktop-table{display:none}.mobile-cards{display:flex;flex-direction:column;gap:12px}.mobile-cards article{padding:14px;background:#fff;border:1px solid #e2e8f0;border-radius:14px}.card-top,.card-actions{display:flex;align-items:center;justify-content:space-between;gap:8px}.mobile-cards p{color:#475569;white-space:pre-wrap;word-break:break-word}.mobile-cards time{color:#64748b;font-size:12px}.card-actions{margin-top:12px}.card-actions .el-button{flex:1;margin:0}.status-filter{width:100%}.task-card-header{gap:10px}}</style>